255	func printTrailDetails(w io.Writer, m *trail.Metadata, webURL, bodyText string) {
256		// Color the same fields as the list view (STATUS/PHASE/AUTHOR); everything
257		// else stays plain. Values are pre-colored, so alignment is unaffected.
258		styles := newStatusStyles(w)
259		status := string(m.Status)
260		if style, ok := trailStatusColor(styles, m.Status); ok {
261			status = styles.render(style, status)
262		}
263		author := m.AuthorLogin()
264		if styles.colorEnabled && author != "" {
265			author = styles.render(styles.cyan, author)
266		}
267	
268		// Field labels and the title line render yellow (matching the list header).
269		label := func(s string) string { return styles.render(styles.yellow, s) }
270	
271		fmt.Fprintf(w, "%s\n", styles.render(styles.yellow, "Trail: "+m.Title))
272		if m.Number > 0 {
273			fmt.Fprintf(w, "  %s%d\n", label("Number:  "), m.Number)
274		}
275		if !m.TrailID.IsEmpty() {
276			fmt.Fprintf(w, "  %s%s\n", label("ID:      "), m.TrailID)
277		}
278		fmt.Fprintf(w, "  %s%s\n", label("Branch:  "), m.Branch)
279		fmt.Fprintf(w, "  %s%s\n", label("Base:    "), m.Base)
280		fmt.Fprintf(w, "  %s%s\n", label("Status:  "), status)
281		fmt.Fprintf(w, "  %s%s\n", label("Author:  "), author)
282		if strings.TrimSpace(m.Phase) != "" {
283			phase := trailPhaseDisplay(m.Phase)
284			if styles.colorEnabled {
285				phase = styles.render(styles.yellow, phase)
286			}
287			fmt.Fprintf(w, "  %s%s\n", label("Phase:   "), phase)
288		}
289		if webURL != "" {
290			fmt.Fprintf(w, "  %s%s\n", label("URL:     "), webURL)
291		}
292		if len(m.Labels) > 0 {
293			fmt.Fprintf(w, "  %s%s\n", label("Labels:  "), strings.Join(m.Labels, ", "))
294		}
295		if len(m.Assignees) > 0 {
296			fmt.Fprintf(w, "  %s%s\n", label("Assignees: "), strings.Join(m.Assignees, ", "))
297		}
298		if strings.TrimSpace(string(m.Type)) != "" {
299			fmt.Fprintf(w, "  %s%s\n", label("Type:      "), m.Type)
300		}
301		if p := strings.TrimSpace(string(m.Priority)); p != "" && p != string(trail.PriorityNone) {
302			fmt.Fprintf(w, "  %s%s\n", label("Priority:  "), m.Priority)
303		}
304		if len(m.Reviewers) > 0 {
305			parts := make([]string, 0, len(m.Reviewers))
306			for _, r := range m.Reviewers {
307				parts = append(parts, fmt.Sprintf("%s (%s)", r.Login, r.Status))
308			}
309			fmt.Fprintf(w, "  %s%s\n", label("Reviewers: "), strings.Join(parts, ", "))
310		}
311		fmt.Fprintf(w, "  %s%s\n", label("Created: "), m.CreatedAt.Format("2006-01-02T15:04:05Z07:00"))
312		fmt.Fprintf(w, "  %s%s\n", label("Updated: "), m.UpdatedAt.Format("2006-01-02T15:04:05Z07:00"))
313		if strings.TrimSpace(bodyText) != "" {
314			fmt.Fprintf(w, "\n%s\n%s\n", label("Description:"), bodyText)
315		}
316	}
