318	// noTrailDescription is shown by `trail show` when a trail's description loaded
319	// successfully but is empty — distinguishing "no description yet" from a load
320	// failure (which warns and renders nothing).
321	const noTrailDescription = "-- no description provided --"
322	
323	// trailDescriptionForDisplay returns the text `trail show` renders for the
324	// description: the body when present; the placeholder when it loaded but is
325	// empty; or "" when it couldn't be loaded (the caller has already warned).
326	func trailDescriptionForDisplay(bodyText string, loaded bool) string {
327		if strings.TrimSpace(bodyText) != "" {
328			return bodyText
329		}
330		if loaded {
331			return noTrailDescription
332		}
333		return ""
334	}
