+		if err != nil {
+			t.Fatalf("attachTrailBranch: %v", err)
+		}
+		if gotMethod != http.MethodPost {
+			t.Fatalf("method = %q, want POST", gotMethod)
+		}
+		if want := "/api/v1/trails/gh/acme/repo/575/branch"; gotPath != want {
